# TABLE SUMMARY WRITER — Append summary table to audit log
# ══════════════════════════════════════════════════════════════════════════


def _write_audit_summary_table(
    log_path: str,
    filepath: str,
    violations: list[Violation],
    patterns_loaded: int,
    elapsed_ms: float,
) -> None:
    """
    AXIOMS: Audit results must be machine-readable and human-readable.
    THEORIES: A table summary provides quick overview without reading full log.
    APPLICATIONS: Append a formatted table to the audit log file.
    CITATIONS: IEEE 829 — Test Documentation Standard
        References:
        - https://docs.python.org/3/library/ast.html
        - https://docs.python.org/3/
    """
    try:
        # Count by severity
        severity_counts: dict[str, int] = {}
        for v in violations:
            sev = v.severity.name if hasattr(v.severity, 'name') else str(v.severity)
            severity_counts[sev] = severity_counts.get(sev, 0) + 1

        # Count by category
        category_counts: dict[str, int] = {}
        for v in violations:
            category_counts[v.category] = category_counts.get(v.category, 0) + 1

        table = []
        table.append("=" * 80)
        table.append("AUDIT SUMMARY TABLE")
        table.append("=" * 80)
        table.append(f"  File: {filepath}")
        table.append(f"  Patterns loaded: {patterns_loaded}")
        table.append(f"  Total violations: {len(violations)}")
        table.append(f"  Analysis time: {elapsed_ms:.1f}ms")
        table.append("-" * 80)
        table.append("  SEVERITY BREAKDOWN:")
        for sev in ["CRITICAL", "HIGH", "MEDIUM", "LOW"]:
            count = severity_counts.get(sev, 0)
            marker = " ***" if count > 0 else ""
            table.append(f"    {sev:10s}: {count:4d}{marker}")
        table.append("-" * 80)
        table.append("  CATEGORY BREAKDOWN:")
        for cat, count in sorted(category_counts.items(), key=lambda x: -x[1]):  # nosec: SMT false positive — dict iteration
            table.append(f"    {cat:35s}: {count:4d}")
        table.append("-" * 80)
        table.append("  VERDICT: ", )
        crit = severity_counts.get("CRITICAL", 0)
        high = severity_counts.get("HIGH", 0)
        if crit > 0:
            table[-1] += "TAINTED (Critical violations found)"
        elif high > 0:
            table[-1] += "CAUTION (High severity issues)"
        else:
            table[-1] += "CLEAN" if len(violations) == 0 else "WARNING (Medium/Low issues)"
        table.append("=" * 80)
        table.append("")

        with open(log_path, "a", encoding="utf-8") as f:
            f.write("\n".join(table) + "\n")
    except (OSError, ValueError, TypeError) as e:
        _verb(f"Failed to write summary table: {e}")


